namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly object _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new Notification(_nextId++, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new Notification(_nextId++, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new Notification(_nextId++, "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    /// <summary>
    /// Returns all notifications currently available.
    /// </summary>
    public List<Notification> GetNotifications()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>
    /// Returns only notifications newer than the given timestamp.
    /// Simulates new notifications arriving over time.
    /// </summary>
    public List<Notification> GetNotificationsSince(DateTime since)
    {
        // Simulate a new notification roughly every 10 seconds
        lock (_lock)
        {
            if (_notifications.Count == 0 || (DateTime.UtcNow - _notifications[^1].Timestamp).TotalSeconds > 10)
            {
                var messages = new[]
                {
                    "You have a new follower!",
                    "Someone commented on your post.",
                    "Your build completed successfully.",
                    "Reminder: team standup in 15 minutes.",
                    "New deployment to production finished.",
                    "Security alert: new login detected.",
                };
                var msg = messages[_nextId % messages.Length];
                _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
            }

            return _notifications.Where(n => n.Timestamp > since).ToList();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    // Runs during both prerender and interactive — loads initial data once.
    protected override void OnInitialized()
    {
        notifications = NotificationService.GetNotifications();
        _lastCheck = notifications.Count > 0
            ? notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    // Only fires once the component is actually interactive in the browser.
    // This is where we start the polling loop — it will NOT run during SSR.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            if (ct.IsCancellationRequested)
                break;

            var newItems = NotificationService.GetNotificationsSince(_lastCheck);
            if (newItems.Count > 0)
            {
                _lastCheck = newItems.Max(n => n.Timestamp);
                await InvokeAsync(() =>
                {
                    notifications.AddRange(newItems);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

