+<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>
+
+@if (notifications.Count == 0)
+{
+    <p><em>No notifications yet.</em></p>
+}
+else
+{
+    <ul class="list-group">
+        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <span>@n.Message</span>
+                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private List<Notification> notifications = new();
+    private CancellationTokenSource? _cts;
+    private DateTime _lastCheck;
+
+    // Runs during both prerender and interactive — loads initial data once.
+    protected override void OnInitialized()
+    {
+        notifications = NotificationService.GetNotifications();
+        _lastCheck = notifications.Count > 0
+            ? notifications.Max(n => n.Timestamp)
+            : DateTime.UtcNow;
+    }
+
+    // Only fires once the component is actually interactive in the browser.
+    // This is where we start the polling loop — it will NOT run during SSR.
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            _cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(_cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken ct)
+    {
+        while (!ct.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);
+
+            if (ct.IsCancellationRequested)
+                break;
+
+            var newItems = NotificationService.GetNotificationsSince(_lastCheck);
+            if (newItems.Count > 0)
+            {
+                _lastCheck = newItems.Max(n => n.Timestamp);
+                await InvokeAsync(() =>
+                {
+                    notifications.AddRange(newItems);
+                    StateHasChanged();
+                });
+            }
+        }
+    }
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+    }
+}
+

